 "安卓数据已重置": "Данные Android сброшены",
 "安卓数据目录已更新": "Папка данных Android обновлена",
 "安卓数据目录（应用、游戏与快速启动快照）": "Папка данных Android (приложения, игры и снимки быстрого запуска)",
 "安卓正在使用快速启动差量盘，就地扩容改不到它。要拿到 {gb} GB 空间，必须按新容量重建 /data。": "Android использует разреженный стартовый снимок, поэтому увеличить его на месте невозможно. Для получения {gb} GB места нужно пересоздать /data заново.",
 "安卓环境只开机一次并常驻；之后打开应用不再重跑整个系统，只启动该应用并停掉其他应用进程。关掉最后一个窗口会清后台、停放容器，下次点开仍是秒进。": "Среда Android загружается один раз и остаётся в памяти; после этого открытие приложения не перезапускает всю систему — запускается только оно, а процессы других приложений останавливаются. Закрытие последнего окна очищает фон и приостанавливает контейнер, но в следующий раз приложение всё равно открывается мгновенно.",
 "安卓的横竖屏是": "Альбомная и портретная ориентация Android",
 "安卓系统设置（不用进安卓桌面）": "Настройки системы Android (без входа в рабочий стол Android)",
 "安卓网络已重置": "Сеть Android сброшена",
 "安卓虚拟机内部的无线网，关掉可省一点 CPU。": "Wi-Fi внутри виртуальной машины Android; если выключить, немного экономится CPU.",
 "安卓虚拟机已联网，联网类应用可以正常加载": "Виртуальная машина Android подключена к сети, сетевые приложения загружаются нормально",
 "安卓虚拟机没有网络时（应用里联网页面一直黑屏/转圈），用这个把安卓数据重置掉来修网络。应用清单会保留，点开应用会自动重装": "Если у виртуальной машины Android нет сети (сетевые страницы в приложениях остаются чёрными или крутят индикатор), сбросьте здесь данные Android, чтобы починить сеть. Список приложений сохранится, при открытии они установятся заново",
 "安卓虚拟机没有网络，联网页面会一直是空白/报错。可在「设置 → 修复网络」处理": "У виртуальной машины Android нет сети, сетевые страницы будут пустыми или с ошибкой. Это можно исправить в «Настройки → Исправить сеть»",
