 "平板排版": "Планшетная вёрстка",
 "平滑模式把一小段时间内的滚动合并成一次滑动手势，避免逐格抽搐，也不会每格都拉起一个 adb 进程。": "Плавный режим объединяет прокрутку за короткий промежуток в один жест, избавляя от рывков по клеткам и не запуская процесс adb на каждую клетку.",
 "平滑（推荐）· 合并多次滚动为一次流畅滑动": "Плавно (рекомендуется) · несколько прокруток объединяются в один плавный свайп",
