 "应用正在独立窗口中运行（顶部可旋转屏幕）。": "Приложение работает в отдельном окне (сверху можно повернуть экран).",
 "应用清单会保留": "Список приложений сохранится",
 "应用窗口": "Окно приложения",
 "应用管理": "Управление приложениями",
 "应用里需要联网的页面一直黑屏/转圈，通常是安卓虚拟机没有网络。": "Если страницы в приложении, которым нужна сеть, постоянно показывают чёрный экран или крутят индикатор, обычно у виртуальной машины Android нет сети.",
 "建议改到纯英文目录": "Рекомендуется выбрать папку только с латинскими буквами",
 "开启「Windows 虚拟机监控程序平台」后重启一次，速度可提升 5~10 倍。": "Включите «Платформу гипервизора Windows» и один раз перезагрузитесь — скорость вырастет в 5–10 раз.",
 "开启后打开新应用不再强制关闭上一个：多个应用可同时驻留、随时快速切回（保留登录态，不必重新加载），切回体验接近多窗口。\n              受限于安卓运行时只有一个模拟器窗口，同一时刻仍只有一个应用画面在前台显示，并非真正的同时并排多窗口。\n              会明显增加内存占用；关闭则回到「一次只显示一个应用」的稳定模式。": "После включения открытие нового приложения больше не принудительно закрывает предыдущее: несколько приложений могут оставаться в памяти и быстро переключаться в любой момент (состояние входа сохраняется, перезагрузка не нужна), переключение почти как в многозадачном режиме.\n              Однако у среды выполнения Android только одно окно эмулятора, поэтому одновременно на переднем плане всё равно отображается только одно приложение — это не настоящее параллельное отображение нескольких окон.\n              Заметно увеличивает расход памяти; при выключении возвращается стабильный режим «одно приложение за раз».",
