 "或右键托盘切换；全屏只放大窗口，不改变画面比例，切换不重启应用。": "Или переключите через контекстное меню в трее; полноэкранный режим только увеличивает окно, не меняя пропорции, переключение не перезапускает приложение.",
 "打不开驱动目录": "Не удаётся открыть папку драйверов",
 "打开": "Открыть",
 "打开 APK 所在位置": "Открыть папку с APK",
 "打开 ApkStart": "Открыть ApkStart",
 "打开 · 每次启动应用都自动全屏": "Включить · каждый запуск приложения сразу в полноэкранном режиме",
 "打开下载页": "Открыть страницу загрузки",
 "打开使用手册（含故障解决方案）": "Открыть руководство (с решениями проблем)",
 "打开内置教程": "Открыть встроенное руководство",
 "打开后，每次点开应用直接铺满屏幕，不用再按 F11。配合下面的「横屏」使用效果最好\n            —— 横屏面板的宽高比本来就贴合屏幕，全屏不会留黑边。": "После включения каждое открытие приложения сразу разворачивается на весь экран, F11 больше не нужен. Лучше всего работает вместе с «альбомной ориентацией» ниже\n            — соотношение сторон альбомной панели и так совпадает с экраном, поэтому в полноэкранном режиме не будет чёрных полос.",
 "打开应用": "Открыть приложение",
 "打开设置": "Открыть настройки",
 "打开驱动目录": "Открыть папку драйверов",
 "打开（推荐 · 逻辑密度 190dpi，sw606dp 走平板排版）": "Открыть (рекомендуется · логическая плотность 190dpi, при sw606dp используется планшетная вёрстка)",
 "打开（默认）· 系统设置里显示自动旋转已开启": "Открыть (по умолчанию) · в системных настройках автоповорот включён",
 "扩容中…": "Увеличение объёма…",
 "扩容失败": "Не удалось увеличить объём",
 "扩容是就地做的：已装应用与存档都保留，只是下次打开应用会多花十几秒。": "Объём увеличивается на месте: установленные приложения и сохранения остаются, только следующее открытие приложения займёт на десять с лишним секунд больше.",
 "扩容需要先关掉正在运行的安卓应用，完成后下次打开应用会重新引导，约多花十几秒。": "Для увеличения объёма нужно сначала закрыть работающее приложение Android; после завершения следующее открытие приложения потребует повторной загрузки и займёт примерно на десять с лишним секунд больше.",
 "扫描失败": "Сканирование не удалось",
 "扫描并清掉旧版本留下的程序目录、失效的卸载项和更新临时文件": "Просканировать и удалить папки программ, нерабочие записи удаления и временные файлы обновлений, оставшиеся от старой версии",
 "扫码关注公众号": "Отсканируйте QR-код и подпишитесь на канал",
 "找到 {n} 项残留，约 {mb} MB：": "Найдено {n} оставшихся элементов, примерно {mb} МБ:",
 "把 APK 拖进来就能装": "Перетащите APK сюда, чтобы установить",
 "把 APK 拖进窗口就能安装，装完会自动生成桌面图标": "Перетащите APK в окно, чтобы установить; после установки значок на рабочем столе создастся автоматически",
 "把报告发给作者可以最快定位问题": "Отправьте отчёт автору — так проблему удастся найти быстрее всего",
 "把键盘按键映射成安卓触屏点击/滑动。适合用键盘玩手游（WASD 移动、J/K 技能等）。\n              每个应用可以单独配置，右键应用卡片 → 「按键映射」选择预设模板或自定义。": "Сопоставляет клавиши клавиатуры с касаниями и свайпами на экране Android. Подходит для мобильных игр с клавиатурой (WASD — движение, J/K — способности и т. п.).\n              Настраивается отдельно для каждого приложения: щёлкните правой кнопкой по карточке приложения → «Раскладка клавиш» и выберите готовый шаблон или настройте вручную.",
 "抖音 · @日常MIKU（联系作者）": "Douyin · @日常MIKU (связаться с автором)",
 "抖音 · 日常MIKU": "Douyin · 日常MIKU",
 "抖音二维码": "二维码（抖音）",
 "拖入 APK 文件，或点击选择": "Перетащите файл APK или нажмите, чтобы выбрать",
 "按 Win+R → 输入 optionalfeatures → 勾选「Windows 虚拟机监控程序平台」": "Нажмите Win+R → введите optionalfeatures → отметьте «Платформа гипервизора Windows»",
 "按下方 6 步完成安装；装好后点「我已安装完成」。": "Выполните установку по 6 шагам ниже; после установки нажмите «Я установил».",
 "按键映射…": "Раскладка клавиш…",
 "按键映射设置失败": "Не удалось сохранить раскладку клавиш",
 "授权弹窗请点「允许」": "В окне запроса разрешения нажмите «Разрешить»",
 "提示：所有应用共享同一个 Android 运行时，所以第二个应用的启动几乎是瞬时的。": "Подсказка: все приложения используют одну среду выполнения Android, поэтому второе приложение запускается почти мгновенно.",
 "搜索已安装应用": "Поиск установленных приложений",
 "搜索设置项：横屏 / 内存 / 代理 / 快照…": "Поиск настроек: альбомная ориентация / память / прокси / снимок…",
