 "支持单个或多个 .apk 文件": "Поддерживается один или несколько файлов .apk",
 "收敛 vCPU 配额并降低进程优先级，CPU 优先让给 Windows 桌面。上面的「资源策略」已经会自动设置这一项。": "Ограничивает квоту vCPU и снижает приоритет процесса, отдавая CPU приоритет рабочему столу Windows. Параметр «Стратегия ресурсов» выше уже задаёт это автоматически.",
