 "有些机器要改启动参数才跑得起来（老显卡 GLES 版本低、没开硬件加速、某版驱动一开硬件渲染就崩）。\n            驱动就是一份 JSON：声明「匹配哪些机器」+「命中后改哪些启动参数」。你可以自己写、导入、分享。\n            驱动只改白名单里的启动项，": "На некоторых компьютерах нужны изменённые параметры запуска, иначе ничего не заработает (старая видеокарта с низкой версией GLES, не включено аппаратное ускорение, определённая версия драйвера падает при включении аппаратного рендеринга).\n            Драйвер — это файл JSON: он объявляет, «каким компьютерам соответствует» и «какие параметры запуска изменить при совпадении». Вы можете писать, импортировать и распространять их сами.\n            Драйвер меняет только пункты запуска из белого списка,",
