 "本机自适应参数": "Адаптивные параметры этого компьютера",
 "本项目仓库已公开，Gitee 的发行版列表匿名就能读，留空也能用 Gitee 源。\n              只有在「Gitee 被限流（返回 403/429）」或你想读私有分支时才需要填：\n              gitee.com → 设置 → 私人令牌，只勾「projects」即可，它只用于读取发行版列表，\n              不会上传任何东西。": "Репозиторий проекта открыт, список релизов Gitee читается анонимно, поэтому источник Gitee работает и с пустым полем.\n              Заполнять нужно только при «ограничении запросов Gitee (ответ 403/429)» или если вы хотите читать приватную ветку:\n              gitee.com → Настройки → Личный токен, достаточно отметить «projects» — он используется только для чтения списка релизов\n              и ничего не загружает.",
