 "模拟器原生把左键当成手指点击，按住拖动就是滑动，无需额外设置。": "Эмулятор по умолчанию считает левую кнопку касанием пальца, а перетаскивание с зажатой кнопкой — свайпом; дополнительная настройка не нужна.",
 "模拟器原生窗口没能显示，本次临时用内置窗口接管画面": "Собственное окно эмулятора не отобразилось, поэтому изображение временно выводится во встроенном окне",
 "模拟器默认把右键也当成一次点击（容易误触）。开启后右键只执行返回，不再触发点击。": "По умолчанию эмулятор считает правую кнопку тоже нажатием (легко промахнуться). После включения правая кнопка выполняет только возврат и больше не вызывает нажатие.",
