 "清理旧版本残留": "Очистить остатки старых версий",
 "清理旧版本残留？": "Очистить остатки старых версий?",
 "清空安卓 /data 用户数据 + 已装应用 + 快速启动快照，还原成刚装好系统的干净状态": "Стереть пользовательские данные Android /data + установленные приложения + снимок быстрого запуска, вернув систему в чистое состояние сразу после установки",
 "清空并重建": "Стереть и пересоздать",
 "清除「{name}」的全部数据？此操作不可撤销。": "Удалить все данные приложения «{name}»? Операция необратима.",
 "清除失败": "Не удалось очистить",
 "清除应用数据": "Очистить данные приложения",
 "清除搜索": "Очистить поиск",
 "游戏 / 低延迟 · 运行时高优先级，适合 FPS、音游": "Игры / низкая задержка · высокий приоритет среды выполнения, подходит для FPS и ритм-игр",
 "游戏提示「存储空间不足」就把这里调大后点「立即扩容」；能就地扩容时不丢已装应用。": "Если игра сообщает «Недостаточно места», увеличьте значение здесь и нажмите «Увеличить сейчас»; при расширении на месте установленные приложения не теряются.",
 "游戏模式会让安卓虚拟机保持较高 CPU 优先级并减少宿主侧轮询，输入与画面延迟最低；代价是整机其他程序会变慢。没有应用窗口时容器仍会自动降优先级停放。": "Игровой режим держит виртуальную машину Android на повышенном приоритете CPU и снижает опрос на стороне хоста, поэтому задержка ввода и изображения минимальна; цена — остальные программы на компьютере работают медленнее. Когда окон приложений нет, контейнер сам снижает приоритет и переходит в ожидание.",
 "滚轮 · 滑动": "Колесо · прокрутка",
 "点「保存并迁移」把旧文件搬过去": "Нажмите «Сохранить и перенести», чтобы перенести старые файлы",
 "点「立即更新」自动下载安装": "Нажмите «Обновить сейчас» для автоматической загрузки и установки",
 "点击托盘图标可重新打开；右键托盘可退出。": "Нажмите значок в трее, чтобы открыть снова; правый клик по значку — выход.",
 "点右侧「修复」会自动开启（需要管理员授权，可能要重启一次）；": "Нажатие «Исправить» справа включит его автоматически (нужны права администратора, возможно, потребуется перезагрузка);",
 "特大": "Очень крупный",
 "现在": "Сейчас",
 "现在双击 APK 会直接安装到 ApkStart": "Теперь двойной щелчок по APK сразу устанавливает его в ApkStart",
 "现在只有一个 Android 14 通用镜像，x86 与 ARM 应用都能跑，首次遇到 ARM 应用时会自动下载，不需要手动切换。此开关仅用于旧配置兼容。": "Сейчас есть только один универсальный образ Android 14, на нём работают и x86-, и ARM-приложения; при первом запуске ARM-приложения он загрузится автоматически, переключать вручную не нужно. Этот переключатель нужен только для совместимости со старыми конфигурациями.",
 "现在可以直接把 APK 拖进来安装了。": "Теперь можно просто перетащить APK сюда, чтобы установить его.",
 "现在把 APK 拖进窗口，或双击桌面图标即可。": "Теперь достаточно перетащить APK в окно или дважды щёлкнуть по значку на рабочем столе.",
 "用的物理面板方向，由上面那条策略自动写入。\n            只有在「强制」模式下它才完全由你决定。": "используется физическая ориентация панели, она задаётся автоматически политикой выше.\n            Полностью в вашем распоряжении она только в режиме «Принудительно».",
 "由 ApkStart 自己分配（emulator-5554，端口冲突时自动顺延），无需填写。": "Назначается самим ApkStart (emulator-5554, при конфликте портов — следующий свободный), заполнять не нужно.",
 "画质（安卓内部渲染分辨率）": "Качество изображения (внутреннее разрешение отрисовки Android)",
 "画面大小已更新": "Размер изображения обновлён",
 "留空 = 桌面": "Пусто = рабочий стол",
 "留空则自动在 PATH / Android SDK 中查找": "Если оставить пустым, поиск выполнится автоматически в PATH / Android SDK",
 "留空即可：公开仓库匿名也能读": "Можно оставить пустым: публичный репозиторий читается и анонимно",
 "的严重问题时弹一次通知，其余都安静地列在下面。": "при серьёзных проблемах показывается одно уведомление, остальное тихо перечислено ниже.",
 "目录不能为空": "Путь к папке не может быть пустым",
 "目标容量不合法": "Недопустимый целевой размер",
 "省资源 · 2 核 / 让出前台 / 540p（老机器、挂机）": "Экономия ресурсов · 2 ядра / уступать активным окнам / 540p (старые машины, работа в фоне)",
 "看不到这台安卓设备 —— 这是刻意的隔离。想连的话用": "Это устройство Android не видно — изоляция сделана намеренно. Чтобы подключиться, используйте",
 "真正吃盘的是这一块：数据分区（默认 6 GB，可在上面对大）+ 快速启动快照（约 2–3 GB）。\n            磁盘紧张时把它指到另一个盘（如 D:），重启软件后生效；旧目录里的": "Основной объём на диске занимает именно это: раздел данных (по умолчанию 6 GB, объём можно увеличить выше) + снимок быстрого запуска (около 2–3 GB).\n            Если на диске тесно, укажите другой диск (например, D:), это вступит в силу после перезапуска программы; файлы в старом каталоге",
