 "系统镜像": "Системный образ",
 "系统镜像全机共享一份，应用数据用差分层保存；旧镜像、旧快照、日志和锁文件都可回收。日志超过上限会自动滚动，不会无限增长。「重置安卓数据」会真实删除数 GB 用户数据，仅保留系统本身。": "Системный образ хранится в одном экземпляре на весь компьютер, данные приложений сохраняются слоями различий; старые образы, старые снимки, журналы и файлы блокировок можно удалить. Журналы по достижении предела автоматически перезаписываются и не растут бесконечно. «Сброс данных Android» действительно удаляет несколько GB пользовательских данных, оставляя только саму систему.",
