 "组件齐全 · 待开机（打开应用时自动拉起）": "Все компоненты на месте · ожидание запуска (запускается при открытии приложения)",
 "组件齐全，双击任意 APK 或桌面图标即会自动开机": "Все компоненты на месте: двойной щелчок по любому APK или значку на рабочем столе запустит систему",
 "给安卓指定国内公共 DNS（阿里 / 腾讯）。安卓默认走主机的 DNS，主机挂着 VPN 或走公司网时解析会拖到几百毫秒，视频类应用首屏发慢。内网域名访问异常时可关掉。": "Задаёт для Android публичный DNS внутри страны (Alibaba / Tencent). По умолчанию Android использует DNS хоста; если на хосте включён VPN или корпоративная сеть, разрешение имён может занимать сотни миллисекунд, и видео-приложения медленнее показывают первый экран. Если домены внутренней сети не открываются, это можно отключить.",
