 "这个 APK 正在安装中，请稍等…": "Этот APK сейчас устанавливается, подождите…",
 "这会把安卓系统还原成「刚装好系统」的干净状态：": "Это вернёт систему Android в чистое состояние «сразу после установки»:",
 "这是运行时": "Это среда выполнения",
 "这里占用空间最大（数 GB）。改到非系统盘可大幅减轻 C 盘压力；修改后需重启软件，已存在的数据不会自动搬移（请手动复制后删除旧目录）。": "Здесь занимается больше всего места (несколько GB). Перенос на несистемный диск заметно разгрузит диск C:; после изменения нужно перезапустить программу, существующие данные автоматически не переносятся (скопируйте вручную, затем удалите старый каталог).",
 "这里的功能还在实验阶段，行为可能随版本变化。遇到问题可在「诊断与修复 → 导出诊断报告」反馈。": "Функции в этом разделе пока экспериментальные, их поведение может меняться от версии к версии. При проблемах сообщите о них через «Диагностика и исправление → Экспортировать отчёт диагностики».",
