 "镜像自动旋转": "Автоповорот изображения",
 "随 Windows 登录常驻托盘，双击桌面图标秒开应用，无需手动启动。": "Работает в трее при входе в Windows, двойной щелчок по значку на рабочем столе мгновенно открывает приложение, запускать вручную не нужно.",
