 "音量已调整": "Громкость изменена",
 "额外禁用 Play 商店、设置向导、打印服务等后台包，只留打开应用必需的环境。若遇到应用提示缺少 Google Play 服务，关掉此开关会自动恢复。": "Дополнительно отключает фоновые пакеты вроде Play Маркета, мастера настройки и службы печати, оставляя только необходимое для запуска приложений. Если приложение сообщает об отсутствии сервисов Google Play, отключите этот переключатель — всё восстановится автоматически.",
