 "（HypervisorPlatform，WHPX 真正需要的那个），确定后重启电脑。": "(HypervisorPlatform — именно тот, что нужен WHPX), затем перезагрузите компьютер.",
 "（为修复网络重置过安卓数据，点开应用会自动重装）": "(данные Android сброшены для исправления сети, при открытии приложения оно установится заново)",
 "（你系统里自己的 adb 是 5037），所以命令行里": "(ваш собственный adb в системе использует 5037), поэтому в командной строке",
 "（商店版无法代你提权，需要你手动操作一次，之后重启。）": "(Версия из магазина не может запросить права за вас, нужно один раз сделать это вручную, затем перезагрузиться.)",
 "（商店版：系统功能只能在「Windows 功能」里手动开）": "(версия из магазина: системные компоненты включаются только вручную в «Компонентах Windows»)",
