 "：进度到 100% 后点下面的「我已安装完成」（ApkStart 会自动重启并接管）": ": когда прогресс достигнет 100%, нажмите ниже «Я установил» (ApkStart перезапустится и всё подхватит)",
 "：选": ": выберите",
 "；匹配不上就不生效。": "; без совпадения не применяется.",
 "；已生成驱动，下次开机会自动套用": "; драйвер создан и будет автоматически применён при следующем запуске",
 "；询问是否使用 GPT 时选": "; когда спросят, использовать ли GPT, выберите",
 "安装失败：这个应用只提供 ARM 原生库（多数国产应用如此），": "Ошибка установки: это приложение содержит только собственные библиотеки ARM (как у большинства отечественных приложений)，",
 "安装失败：与已安装版本签名不一致，请先卸载旧版再装。": "Ошибка установки: подпись не совпадает с подписью установленной версии. Сначала удалите старую версию, затем устанавливайте.",
 "安装失败：APK 路径含特殊字符，请把文件移到纯英文路径后重试。": "Ошибка установки: путь к APK содержит специальные символы. Переместите файл в каталог только с латинскими буквами и повторите попытку.",
 "ApkStart 会自动用官方绕过参数重试。": "ApkStart автоматически повторит попытку с официальными параметрами обхода.",
 "安装失败：与已有应用的 ContentProvider 冲突，请卸载冲突应用。": "Ошибка установки: конфликт ContentProvider с уже установленным приложением. Удалите конфликтующее приложение.",
 "ApkStart 会自动切换到 Android 14 兼容镜像后重试。": "ApkStart автоматически переключится на совместимый образ Android 14 и повторит попытку.",
