 "8-数据与目录说明": "8-Описание данных и каталогов",
 "新通知": "Новое уведомление",
 "显存很小（或读不到），用 swangle 更稳": "Видеопамять очень мала (или не определяется); надёжнее использовать swangle",
 "这颗 CPU 不支持硬件虚拟化": "Этот процессор не поддерживает аппаратную виртуализацию",
 "联想/戴尔/华硕一般在 Advanced → CPU Configuration 里；品牌机可能叫 Virtualization Technology。": "У Lenovo/Dell/ASUS это обычно находится в Advanced → CPU Configuration; на фирменных ПК может называться Virtualization Technology.",
 "读不到 CPU 虚拟化状态": "Не удалось определить состояние виртуализации процессора",
 "Hypervisor 正在运行，WHPX 可用。": "Гипервизор запущен, WHPX доступен.",
 "（HypervisorPlatform）与「虚拟机平台」→ 确定 → 重启。": "（HypervisorPlatform）и «Платформа виртуальных машин» → ОК → Перезагрузка.",
 "硬件加速可用（{v.accelKind === 'aehd' ? 'AEHD' : 'WHPX'}）": "Аппаратное ускорение доступно ({v.accelKind === 'aehd' ? 'AEHD' : 'WHPX'})",
 "会先用软件模拟保证能跑；速度比硬件加速慢 5~10 倍。": "Сначала будет использована программная эмуляция, чтобы обеспечить запуск; она в 5~10 раз медленнее аппаратного ускорения.",
