 "由「本机体检 · 自动配置」生成：{gpuRec.why}。{v.accelOk ? '硬件加速可用。' : '当前无硬件加速。'}": "Создано с помощью «Проверка этого компьютера · Автоматическая настройка»: {gpuRec.why}. {v.accelOk ? '硬件加速可用。' : '当前无硬件加速。'}",
 "或先清理磁盘 / 卸载不用的应用后再试。": "Или сначала очистите диск / удалите неиспользуемые приложения и попробуйте снова.",
 "未检测到 Windows Hypervisor Platform 组件：可在「启用或关闭 Windows 功能」中勾选「虚拟机平台」后重启": "Компонент Windows Hypervisor Platform не обнаружен: установите флажок «Платформа виртуальных машин» в «Включение и отключение компонентов Windows» и перезагрузитесь",
 "下载 Android platform-tools（约 8MB）…": "Загрузка Android platform-tools (около 8MB)…",
 "adb {v.version} 就绪": "adb {v.version} готов",
