 "{issues.length} 项提示": "{issues.length} подсказок",
 "当前系统镜像没有 ARM 转译层。ApkStart 会自动切换到内置新版翻译层的兼容镜像并重试。": "В текущем системном образе нет слоя трансляции ARM. ApkStart автоматически переключится на совместимый образ со встроенным новым слоем трансляции и повторит попытку.",
 "安装失败：设备上已安装更高版本，不能降级覆盖。": "Ошибка установки: на устройстве установлена более новая версия, понижение невозможно.",
 "安装失败：已存在同名应用且签名不同，请先卸载。": "Ошибка установки: приложение с таким именем уже существует, но подпись отличается. Сначала удалите его.",
 "安装失败：这是仅供测试的应用包，已自动加上测试包参数重试。": "Ошибка установки: это пакет только для тестирования, параметр тестового пакета добавлен автоматически, повторяем попытку.",
 "安装失败：系统内部错误（常见于存储空间不足或开机未完成），请重启运行时后重试。": "Ошибка установки: внутренняя ошибка системы (часто из-за нехватки места на диске или незавершённой загрузки). Перезапустите среду выполнения и повторите попытку.",
