 "上次没有正常关机的安卓进程还占着资源与 AVD 锁，会让下次开机失败。可以一键清理（不会动已装应用与存档）。": "Прошлый процесс Android, завершившийся некорректно, всё ещё занимает ресурсы и блокировку AVD — из-за этого следующий запуск может завершиться ошибкой. Можно очистить в один клик (установленные приложения и сохранения не затрагиваются).",
 "安卓侧弹过「允许 USB 调试吗」但没被确认，adb 一直连不上。重启运行时（走一次冷启动）会重新弹出确认框，确认后即恢复。": "На стороне Android появлялось окно «Разрешить отладку по USB?», но оно не было подтверждено, поэтому adb не подключается. Перезапуск среды (холодный запуск) снова покажет диалог подтверждения; после подтверждения всё восстановится.",
 "安卓进程活着、adb 却看不到设备，多半是 adb 服务端口被别的程序占了，或者引导还没完成。": "Процесс Android работает, но adb не видит устройство — скорее всего, порт сервиса adb занят другой программой либо загрузка ещё не завершилась.",
