 "只能走软件模拟，速度会慢 5~10 倍。轻量应用还能用，大型游戏不建议。": "Доступна только программная эмуляция — скорость будет в 5–10 раз ниже. Лёгкие приложения ещё работают, крупные игры не рекомендуются.",
