 "显卡驱动比较旧": "Драйвер видеокарты устарел",
 "ApkStart 最低支持 Windows 10 2004（build 19041）。更旧的系统上 emulator 可能直接退出。": "ApkStart поддерживает Windows 10 2004 (build 19041) и новее. На более старых системах emulator может сразу завершаться.",
 "这台机器可以直接跑硬件加速，配置已经是最优": "На этом компьютере можно использовать аппаратное ускорение напрямую, конфигурация уже оптимальна",
