 "窗口代理连接断开": "Соединение с агентом окна потеряно",
 "缺少 AndroidManifest.xml：这不是单个 APK（可能是 .apks/.xapk 拆分包）": "Отсутствует AndroidManifest.xml: это не одиночный APK (возможно, разделённый пакет .apks/.xapk)",
 "正在切回竖屏（重启安卓运行时，约 30-60 秒）…": "Переключаемся обратно на портретную ориентацию (перезапуск среды Android, около 30-60 сек.)…",
 "安卓虚拟机进程、启动阶段、快照与残留锁": "Процессы виртуальной машины Android, этапы загрузки, снимки и оставшиеся блокировки",
 "安卓网络与下载源连通性": "Сеть Android и доступность источников загрузки",
 "安卓开机卡在引导阶段": "Загрузка Android зависает на этапе инициализации",
 "锁文件没清会让下一次启动被判定为「AVD 已被占用」而直接失败。可以一键清掉。": "Если не удалить файл блокировки, следующий запуск будет расценен как «AVD уже используется» и сразу завершится ошибкой. Можно очистить в один клик.",
 "快照文件还在但校验不通过，每次开机都要额外冷启动一次。删掉它会用一次冷启动换回磁盘空间。": "Файл снимка есть, но проверка не проходит, поэтому при каждом запуске приходится дополнительно делать холодный запуск. Удаление вернёт место на диске ценой одного холодного запуска.",
 "adb 能看到设备但连不上，通常是虚拟机还在引导或 adb 服务没握手成功。等一会儿仍不恢复就重启运行时。": "adb видит устройство, но не подключается: обычно виртуальная машина ещё загружается или службе adb не удалось установить соединение. Если через некоторое время не восстановится, перезапустите среду выполнения.",
 "剩余空间不足 2 GB，装应用和写快照都会失败。点「一键清理」回收旧镜像、旧快照和日志。": "Осталось меньше 2 GB: установка приложений и запись снимков будут завершаться ошибкой. Нажмите «Очистить в один клик», чтобы освободить место, удалив старые образы, снимки и журналы.",
 "数据分区扩容没有真正生效": "Увеличение раздела данных не вступило в силу",
 "安卓里实际可用容量小于设置里写的值，装大游戏会提示存储空间不足。": "Фактический доступный объём в Android меньше значения, указанного в настройках, поэтому при установке крупных игр появляется сообщение о нехватке места.",
 "策略要求竖屏，但面板现在是横屏，安卓只会给应用一条窄画面加两侧黑边。把面板方向改成与策略一致即可。": "Политика требует портретной ориентации, а панель сейчас в альбомной: Android выделит приложению узкую полосу с чёрными полями по бокам. Достаточно изменить ориентацию панели в соответствии с политикой.",
 "磁盘偏紧，快速启动快照已关闭": "Мало места на диске: снимок быстрого запуска отключён",
 "Windows 音频服务（Audiosrv）未运行": "Служба звука Windows (Audiosrv) не запущена",
