 "当前没有硬件加速": "Аппаратное ускорение сейчас недоступно",
 "APK 清单为空": "Манифест APK пуст",
 "该后端不支持调整数据分区": "Этот бэкенд не поддерживает изменение размера раздела данных",
 "首次启动约 25 秒，之后靠 quickboot 快照秒进。": "Первый запуск занимает около 25 секунд, затем снимок quickboot обеспечивает почти мгновенный вход.",
 "缺 Android Emulator": "Отсутствует Android Emulator",
 "自带运行时的内存/CPU 下次启动安卓生效；数据分区改大后点「立即扩容」——": "Изменения памяти/CPU встроенной среды вступят в силу при следующем запуске Android; после увеличения раздела данных нажмите «Расширить сейчас»——",
 "容器活跃：{n} 个应用窗口${plan && plan.stopped && plan.stopped.length\n    ?": "Контейнер активен: {n} окон приложений${plan && plan.stopped && plan.stopped.length\n    ?",
