 "模拟器端口被占用": "Порт эмулятора занят",
 "系统镜像缺失或损坏 / 与旧用户数据不兼容": "Системный образ отсутствует, повреждён / несовместим со старыми данными пользователя",
 "请打开内置手册 6.8 按步骤定位；不要只凭这一条就重装运行库。": "Откройте встроенное руководство, раздел 6.8, и следуйте шагам для поиска причины; не переустанавливайте среду выполнения только на основании этой ошибки.",
