 "分块失败（{c.start}-{c.end}）：{e.message}": "Ошибка загрузки фрагмента ({c.start}-{c.end}): {e.message}",
 "会改数据分区大小，请走设置页": "Это изменит размер раздела данных, используйте страницу настроек",
 "match 必须是对象": "match должен быть объектом",
 "effect.emulatorArgs 必须是字符串数组": "effect.emulatorArgs должен быть массивом строк",
 "emulatorArgs 的 {flag} 取值不合法：{value}": "Недопустимое значение {flag} в emulatorArgs: {value}",
