 "读不出来：{e.message}": "Не удалось прочитать: {e.message}",
 "{name} 兼容补丁": "{name} — патч совместимости",
 "启动参数或环境错误": "Ошибка в параметрах запуска или окружении",
 "0xC0000022 拒绝访问（驱动或权限问题）": "0xC0000022 Отказ в доступе (проблема с драйвером или правами)",
 "userdata 扩容：文件 {size} → {wantBytes}，文件系统 {fsBytes} → {grown}": "Расширение userdata: файл {size} → {wantBytes}, файловая система {fsBytes} → {grown}",
 "qemu-img {op} 失败: {(r.stderr || '').trim() || r.status}": "Ошибка qemu-img {op}: {(r.stderr || '').trim() || r.status}",
 "关掉 ApkStart 再打开又要冷启动 20 多秒": "Если закрыть ApkStart и открыть снова, потребуется ещё более 20 секунд холодного запуска",
 "可以再点一次「立即扩容」，或清理磁盘后重试。": "Можно нажать «Расширить сейчас» ещё раз или повторить после очистки диска.",
 "把它改到空间充足的盘（例如 D:），或先清理磁盘。你的应用与存档不会被自动删除。": "Переместите его на диск с достаточным местом (например, D:), или сначала очистите диск. Ваши приложения и сохранения не будут удалены автоматически.",
 "未匹配到任何驱动，按默认参数启动": "Драйверы не подобраны, запуск с параметрами по умолчанию",
 "驱动要求关闭硬件加速（走软件模拟）": "Драйвер требует отключить аппаратное ускорение (переход на программную эмуляцию)",
 "磁盘空间不足，已停止重试（不会动你的应用与存档）。": "Недостаточно места на диске, повторы остановлены (ваши приложения и сохранения не затрагиваются).",
 "需要联网的应用打开后可能一直黑屏：稍后重开应用即可；": "Приложению, требующему интернета, после открытия может долго показывать чёрный экран: просто откройте его позже；",
 "运行时多次尝试仍未能启动（{d.title}）。\n{d.hint}": "Среде выполнения не удалось запуститься после нескольких попыток ({d.title}).\n{d.hint}",
 "缺少 adb：点击「一键部署」自动下载": "Отсутствует adb: нажмите «Развернуть в один клик» для автоматической загрузки",
 "模拟器停在「允许 USB 调试？」对话框。请在那个模拟器窗口里点「允许」——": "Эмулятор завис на диалоге «Разрешить отладку по USB?». В окне эмулятора нажмите «Разрешить»——",
