 "怎么都开不了机": "Никакими способами не удаётся загрузиться",
 "检测到卡住的运行时，正在重启…": "Обнаружена зависшая среда выполнения, выполняется перезапуск…",
 "运行时组件尚未部署完成": "Компоненты среды выполнения ещё не развёрнуты полностью",
 "方向自愈：init={init[1]}x{init[2]} cur={cur[1]}x{cur[2]} 已躺倒，重新收敛": "Автоисправление ориентации: init={init[1]}x{init[2]} cur={cur[1]}x{cur[2]}, устройство повёрнуто на бок, выполняется повторная настройка",
 "网络已恢复（{net.ip || ''}），正在保存可用状态，下次直接就好。": "Сеть восстановлена ({net.ip || ''}), сохраняем рабочее состояние, в следующий раз всё заработает сразу.",
 "网络已恢复（{net1.ip || ''}），已存好可用快照。": "Сеть восстановлена ({net1.ip || ''}), рабочий снимок сохранён.",
 "网络已恢复（{network.ip || ''} 网关 {network.gateway || '可达'}），已存好可用快照。": "Сеть восстановлена ({network.ip || ''}, шлюз {network.gateway || '可达'}), рабочий снимок сохранён.",
 "增量清单缺少版本信息": "В манифесте инкрементального обновления нет информации о версии",
 "Electron 版本不同，需要完整包": "Версия Electron отличается, требуется полный пакет",
 "拆分包的 base APK 解析失败": "Не удалось разобрать базовый APK разделённого пакета",
 "切换兼容镜像后运行时不可用": "После переключения на совместимый образ среда выполнения не работает",
 "正在准备安卓运行时…": "Подготовка среды выполнения Android…",
 "正在安装应用…": "Установка приложения…",
 "请检查磁盘空间与网络后重试；若一直失败，到「设置 → 诊断与修复」导出诊断报告反馈。": "Проверьте место на диске и сеть, затем повторите; если ошибка повторяется, экспортируйте диагностический отчёт в «Настройки → Диагностика и восстановление» и отправьте его.",
 "应用图标无法解析（可能是特殊格式的自适应图标），快捷方式暂时使用占位图标。": "Не удалось разобрать значок приложения (возможно, адаптивный значок в нестандартном формате), для ярлыка временно используется значок-заглушка.",
 "显示适配跳过：{e.message}": "Адаптация отображения пропущена: {e.message}",
 "虚拟机网络还没就绪，先启动应用（联网页面可能稍后才加载出来）": "Сеть виртуальной машины ещё не готова, запускаем приложение (страницы, требующие интернета, могут загрузиться позже)",
