 "使用手册 · 目录": "Руководство пользователя · Содержание",
 "安装失败（INSTALL_FAILED_*）": "Ошибка установки (INSTALL_FAILED_*)",
 "adb 未授权（允许 USB 调试）": "adb не авторизован (разрешите отладку по USB)",
 "其它启动类问题速查表": "Таблица быстрого поиска других проблем с запуском",
 "商店版启动失败 / 0xC0000135（DLL 加载失败）": "Ошибка запуска версии из магазина / 0xC0000135 (не удалось загрузить DLL)",
 "设置页导航": "Навигация по странице настроек",
 "自动检测与网络修复": "Автоматическая проверка и восстановление сети",
 "显卡型号读不到，交给自动降级链去试": "Не удалось определить модель видеокарты, попробуем автоматическую цепочку понижения настроек",
 "Intel 核显对 GLES 支持参差，swangle 更稳": "Встроенная графика Intel по-разному поддерживает GLES, swangle работает стабильнее",
 "重启进 BIOS/UEFI，把 Intel VT-x（Intel）或 SVM Mode（AMD）设为 Enabled，保存后回来重新体检。": "Перезагрузитесь в BIOS/UEFI, включите Intel VT-x (для Intel) или SVM Mode (для AMD), сохраните изменения и вернитесь, чтобы пройти проверку снова.",
 "{cpu.name} · {cpu.cores || '?'} 核 / {cpu.threads || '?'} 线程": "{cpu.name} · {cpu.cores || '?'} ядер / {cpu.threads || '?'} потоков",
 "Windows 虚拟机监控程序平台已启用": "Платформа гипервизора Windows включена",
 "商店版不能自行改系统功能。按 Win+R → 输入 optionalfeatures → 勾选「Windows 虚拟机监控程序平台」": "Версия из магазина не может самостоятельно изменять компоненты системы. Нажмите Win+R → введите optionalfeatures → установите флажок «Платформа гипервизора Windows»",
 "一键开启（需管理员）": "Включить в один клик (требуются права администратора)",
 "可以装 AEHD 驱动（需管理员），或先开「虚拟机监控程序平台」后重启；两者都不行就只能软件模拟。": "Можно установить драйвер AEHD (нужны права администратора) или сначала включить «Платформу гипервизора Windows» и перезагрузиться; если ни один из способов не подходит, остаётся только программная эмуляция.",
 "可能是远程桌面 / 虚拟机 / 驱动异常。渲染后端交给自动降级链处理。": "Возможно, причина в удалённом рабочем столе / виртуальной машине / сбое драйвера. Выбор бэкенда рендеринга доверен автоматической цепочке понижения.",
 "安卓虚拟机最多只能分 2 GB、2 核，画质降到 540×960，并建议关掉浏览器标签页再开应用。": "Виртуальной машине Android можно выделить не более 2 GB и 2 ядер, качество снижено до 540×960; рекомендуется также закрыть вкладки браузера перед запуском приложения.",
 "ApkStart 体检": "Проверка ApkStart",
 "建议：把「运行时数据目录」改到空间更大的盘（设置 → 系统集成 → 运行时数据目录 → 浏览），": "Рекомендация: переместите «Каталог данных среды выполнения» на диск с большим объёмом (Настройки → Интеграция с системой → Каталог данных среды выполнения → Обзор)，",
 "虚拟机平台组件存在（可用性由运行时引擎检测）": "Компонент платформы виртуальных машин присутствует (доступность проверяется движком среды выполнения)",
 "Android {PLAY_SYSIMG.api}（{playImage.compressed ? '包内压缩版，首次启动自动展开' : 'ARM 兼容镜像'}）": "Android {PLAY_SYSIMG.api} ({playImage.compressed ? '包内压缩版，首次启动自动展开' : 'ARM 兼容镜像'})",
