 "（约 1.3 GB）": "(около 1.3 GB)",
 "只想先试试，首次启动再联网下载运行时": "Хотите просто попробовать: среда выполнения скачивается из сети при первом запуске",
 "：adb、Android Emulator、Android 14 系统镜像，官方源实测 10+ MB/s，8 线程分块 + 断点续传。完整版 / 商店版跳过此步。": ": adb, Android Emulator, системный образ Android 14: официальный источник показывает 10+ MB/s, 8 потоков, разбиение на части + докачка. Полная версия / версия из магазина пропускают этот шаг.",
 "首次造": "При первом создании",
 "，冷启动约 23 秒，命中快照约 10 秒。": ", холодный запуск около 23 сек, при использовании снимка около 10 сек.",
 "（先注册关联：设置 → 系统集成 → 关联 .apk 文件）；": "(сначала зарегистрируйте ассоциацию: «Настройки» → «Системная интеграция» → «Ассоциация файлов .apk»);",
 "支持": "Поддерживается",
 "第二个应用几乎瞬时启动": "Второе приложение запускается почти мгновенно",
 "或右键托盘菜单。全屏只放大窗口、不改画面比例": "или через контекстное меню в трее. Полноэкранный режим только увеличивает окно, не меняя пропорции изображения.",
 "强制横屏/竖屏": "Принудительная альбомная/портретная ориентация",
