 "鼠标键位、键盘映射": "Привязка кнопок мыши, раскладка клавиатуры",
 "桌面与应用、文件互通、系统集成": "Рабочий стол и приложения, обмен файлами, системная интеграция",
 "：打开后，新应用不再强制关闭上一个，多个应用可驻留后台、随时切回且保留登录态。受限于安卓运行时只有一个模拟器窗口，同一时刻仍只有一个应用画面在前台显示，并非真正并排多窗口；开启会增加内存占用。默认关闭，追求稳定可忽略它。": ": после включения новое приложение не закрывает предыдущее: несколько приложений могут оставаться в фоне, переключаться в любой момент и сохранять состояние авторизации. Из-за того что Android-среда использует только одно окно эмулятора, в каждый момент на переднем плане всё равно отображается только одно приложение — это не настоящие параллельные окна. Включение увеличивает расход памяти. По умолчанию отключено; если важна стабильность, можно не включать.",
 "：每次发版会额外发布一份「代码清单」和一个只含程序代码的小包（几 MB，整个安装包约 100 MB）。如果你的 Electron 外壳版本没变，更新只下载这个小包、逐个文件校验后替换程序代码，几秒就好；外壳版本变了、清单缺失或任何校验不通过，会自动退回下载完整包，不会把程序更新坏。商店版仍由 Microsoft Store 负责更新。": ": с каждым выпуском дополнительно публикуется «манифест кода» и небольшой пакет только с кодом программы (несколько MB, весь установочный пакет — около 100 MB). Если версия оболочки Electron не изменилась, обновление скачивает только этот небольшой пакет, проверяет каждый файл и заменяет код программы — это занимает несколько секунд; если версия оболочки изменилась, манифест отсутствует или какая-либо проверка не прошла, программа автоматически вернётся к загрузке полного пакета и не повредит программу. Версия из Microsoft Store обновляется через сам Microsoft Store.",
 "完整的 Android 14 系统镜像": "Полный системный образ Android 14",
 "镜像缺失 / 损坏 / 与旧用户数据不兼容 → 开机失败、卡在引导、反复重启。": "Образ отсутствует / повреждён / несовместим со старыми данными пользователя → сбой загрузки, зависание на старте, повторяющиеся перезагрузки.",
