 "在翻本手册之前，先让软件自己查一遍——大多数问题它能自动修。": "Прежде чем листать это руководство, позвольте программе самой всё проверить — большинство проблем она исправляет автоматически.",
 "点「": "Нажмите «",
 "（能用但建议优化）/": "(работает, но рекомендуется оптимизировать)/",
 "：重启进 BIOS → 打开 Intel VT-x / AMD SVM → Enabled（这一步软件无法代劳）。": ": перезагрузитесь в BIOS → включите Intel VT-x / AMD SVM → Enabled (это программа не может сделать за вас).",
 "后台每 10 分钟把机器查一遍，按六类列问题，每条可": "В фоновом режиме компьютер проверяется каждые 10 минут, проблемы группируются по шести категориям, и для каждой можно",
 "上次启动失败的真实原因、引导卡死、残留锁文件、孤儿模拟器进程、快照空壳、没有硬件加速": "реальная причина прошлого сбоя запуска, зависание загрузки, оставшиеся файлы блокировок, «осиротевшие» процессы эмулятора, пустая оболочка снимка, отсутствие аппаратного ускорения",
 "网络/日志": "Сеть/журналы",
 "报告是纯文本，含本机配置、自动选中的启动参数、日志和诊断结论。反馈问题时附上它，能大幅加快定位。": "Отчёт — это обычный текст: конфигурация компьютера, автоматически выбранные параметры запуска, журналы и выводы диагностики. Прикрепите его при отправке отзыва — это сильно ускорит поиск причины.",
 "自动检测/修复也会把教程送到你面前：": "Автоматическая проверка/восстановление также подскажет нужную инструкцию:",
 "，不用再来这里翻；": ", не нужно возвращаться сюда;",
