 "。会弹一次 UAC，自动开启 WHPX；若开不起来（系统不支持或你点了否），会自动改装 AEHD 驱动。": ". Появится один раз запрос UAC, WHPX включится автоматически; если не получится (система не поддерживает или вы нажали «Нет»), автоматически установится драйвер AEHD.",
 "，点「修复」会打开「启用或关闭 Windows 功能」对话框：": ", нажмите «Исправить» — откроется диалог «Включение или отключение компонентов Windows»:",
