 "ApkStart 会把英文原始错误翻译成中文。对照下表处理：": "ApkStart переведёт исходное сообщение об ошибке с английского на китайский. Действуйте по таблице ниже:",
 "应用只提供 ARM 库，当前镜像没有 ARM 转译层": "Приложение содержит только ARM-библиотеки, а в текущем образе нет уровня трансляции ARM",
 "需更高系统镜像；当前为 Android 14（API 34），极少触发": "Требуется более новый системный образ; сейчас Android 14 (API 34), встречается крайне редко",
