 "若报的是上表之外的原始英文，直接按 5.3 导出诊断报告反馈。": "Если выведено исходное сообщение на английском, не указанное в таблице выше, сразу экспортируйте диагностический отчёт по п. 5.3 и отправьте его.",
 "：0.6.3 用": ": в 0.6.3 используется",
 "ApkStart 会自动做什么：": "Что ApkStart делает автоматически:",
 "），自动切到 Android 14 兼容镜像重试（日志\"检测到 ARM 翻译层崩溃，正在自动切换兼容镜像…\"）。": "), автоматически переключается на совместимый образ Android 14 и повторяет запуск (в журнале: «Обнаружен сбой уровня трансляции ARM, автоматически переключаемся на совместимый образ…»).",
