 "旧版（0.5.x）没有内置运行时、默认嵌入窗口 → \"很慢 + 带旋转按钮的壳窗口\"。换成 0.6.3，并把快捷方式指到新版": "Старая версия (0.5.x) не имеет встроенной среды выполнения и по умолчанию встраивает окно → «медленно + окно-оболочка с кнопкой вращения». Перейдите на 0.6.3 и направьте ярлык на новую версию",
 "：连点会让第二个实例接管模拟器，而第一个实例退出时的收尾可能把模拟器一起关掉，导致失败（0.6.3 已加": ": при частых щелчках второй экземпляр перехватывает эмулятор, а завершение первого экземпляра может закрыть эмулятор вместе с ним, что приводит к сбою (в 0.6.3 добавлена",
 "，说明窗口代理没找到模拟器窗口，程序退回嵌入模式（就是你看到的带标题栏+旋转按钮的壳窗口）。": ", значит прокси окна не нашёл окно эмулятора, и программа вернулась во встроенный режим (то есть та самая оболочка с заголовком + кнопкой вращения, которую вы видите).",
 "（有二次确认）。会清掉已装应用和数据，但保留系统本身，应用清单保留、点开会自动重装。适用于数据分区损坏、": "(с дополнительным подтверждением). Удаляет установленные приложения и данные, но сохраняет саму систему; список приложений остаётся, и при открытии они переустанавливаются автоматически. Подходит при повреждении раздела данных,",
 "；下表说明它做了什么、以及你还能做什么。若自动处理无效，按 5.3 导出诊断报告。": "; в таблице ниже указано, что она делает и что ещё вы можете сделать. Если автоматическая обработка не помогла, экспортируйте диагностический отчёт по п. 5.3.",
 "按 6.1 开启加速": "Включите ускорение по п. 6.1",
