 "系统镜像缺失/损坏/与旧数据不兼容": "Системный образ отсутствует/повреждён/несовместим со старыми данными",
 "下次正常退出会重建；或关掉快照": "При следующем корректном выходе он будет создан заново; или отключите снимки",
 "路径含中文/特殊字符": "Путь содержит китайские/специальные символы",
 "多为警告仍可开机；否则换支持 VT-x/AVX 的机器或旧版引擎": "В большинстве случаев это предупреждения, загрузка всё равно возможна; иначе используйте машину с поддержкой VT-x/AVX или более старый движок",
 "更新显卡驱动；或写兼容补丁；仍不行导出诊断报告": "Обновите драйвер видеокарты; или напишите патч совместимости; если не помогло — экспортируйте диагностический отчёт",
 "：安卓应用里视频、提示音完全没声；或 Windows 其它软件有声、只有 ApkStart 里的应用没声。": ": в Android-приложении полностью отсутствует звук видео и уведомлений; либо в других программах Windows звук есть, а в приложениях ApkStart — нет.",
 "：点任务栏音量图标，确认没有静音、音量不为 0，输出设备选的是你正在用的耳机/音箱。打开「音量合成器」，看 ApkStart / 安卓运行时那一行是不是被单独静音或拉到 0。": ": щелкните по значку громкости на панели задач, убедитесь, что звук не выключен, громкость не равна 0, а выходное устройство — те наушники/колонки, которыми вы пользуетесь. Откройте «Микшер громкости» и посмотрите, не приглушена ли отдельно строка ApkStart / Android-среда или не выставлена ли она в 0.",
