 "：切到蓝牙耳机后 Windows 有时不会把已运行的程序迁过去。断开重连耳机，或重启一次安卓运行时。": ": после переключения на Bluetooth-наушники Windows иногда не переносит уже запущенные программы. Отключите и снова подключите наушники или один раз перезапустите Android-среду.",
 "手动进来。": "Откройте вручную.",
