 "不等于": "Не равно",
 "目录里。安卓运行时从这个目录拉起": "в каталоге. Android-среда запускается из этого каталога",
 "：安卓运行时（Qt6 / qemu）依赖微软 VC++ 2015-2022（x64）。设置 → 诊断与修复里若明确报「缺少 VC++ 运行库（x64）」，那是": ": Android-среда (Qt6 / qemu) зависит от Microsoft VC++ 2015-2022 (x64). Если в разделе «Настройки» → «Диагностика и восстановление» прямо указано «Отсутствует библиотека VC++ (x64)», это",
 "：运行时目录里的 dll 被隔离 / 删除，也会报这个码。把 ApkStart 的安装目录和运行时数据目录加入杀毒白名单，再重新安装一次。": ": если dll в каталоге среды выполнения помещён в карантин / удалён, тоже появляется этот код. Добавьте каталог установки ApkStart и каталог данных среды выполнения в белый список антивируса, затем переустановите.",
 "不要": "Не нужно",
 "：这是当前最可能的原因。依次试：": ": это наиболее вероятная причина на данный момент. Попробуйте по порядку:",
 "便携版": "Портативная версия",
 "想拿到确切的失败 DLL 名": "Чтобы узнать точное имя сбойной DLL",
 "adb 也崩溃怎么办": "Что делать, если аварийно завершается и adb",
 "这一节会自动弹出：当启动失败 / 修复失败被判定为 DLL 类问题时，软件会直接打开到这里。也可随时从自动检测条目的「教程」按钮或标题栏": "Этот раздел открывается автоматически: когда сбой запуска / сбой восстановления определены как проблема с DLL, программа сразу переводит сюда. Также можно зайти вручную в любой момент через кнопку «Руководство» в пункте автоматической проверки или через строку заголовка",
 "位置": "Расположение",
