 "8. 数据与目录说明": "8. Данные и каталоги",
 "本手册先教你怎么用，再按「症状」给出可照做的解决方案。所有步骤都对应软件里真实存在的按钮和菜单。": "В этом руководстве сначала объясняется, как пользоваться программой, затем по «симптомам» приведены готовые решения. Все шаги соответствуют реально существующим в программе кнопкам и меню.",
 "理解三个核心概念（看懂报错的关键）": "Три ключевых понятия (ключ к пониманию ошибок)",
 "获取帮助与反馈": "Помощь и обратная связь",
 "：在资源管理器里注册文件关联后，双击 APK → 自动解析 → 安装 → 生成桌面图标。": ": после регистрации ассоциации файлов в Проводнике: двойной щелчок по APK → автоматический разбор → установка → создание значка на рабочем столе.",
 "：原生渲染，全屏铺满屏幕高度并居中，窗口模式可拖动缩放，每个应用单独记忆尺寸。": ": нативный рендеринг; в полноэкранном режиме изображение заполняет всю высоту экрана по центру, в оконном режиме окно можно перемещать и изменять размер, размер каждого приложения запоминается отдельно.",
 "）双快捷方式。": ") два ярлыка.",
 "自带运行时": "Встроенная среда выполнения",
 "（国内直连快得多）": "(прямое соединение внутри страны гораздо быстрее)",
 "商店版": "Версия из магазина",
 "（约 830 MB，解压 ~1.3 GB）": "(около 830 MB, после распаковки ~1.3 GB)",
 "想要桌面/开始菜单快捷方式和卸载项": "Нужны ярлыки на рабочем столе / в меню «Пуск» и пункт удаления",
 "务必用最新版（当前 0.6.3）": "Обязательно используйте последнюю версию (сейчас 0.6.3)",
 "首次展开镜像": "Первое развёртывание образа",
 "：ApkStart 自己生成带加密和 SELinux 标签的 ext4 用户数据（官方镜像里只是 1 MB 占位）。": ": ApkStart сам создаёт пользовательские данные ext4 с шифрованием и метками SELinux (в официальном образе это просто заглушка 1 MB).",
 "首次启动慢是正常的，属\"一次性成本\"。之后再用就是秒进。": "Медленный первый запуск — это нормально, это \"разовая плата\". После этого запуск занимает считанные секунды.",
