 "APK 损坏/不完整": "APK повреждён / неполный",
 "已存在同名且签名不同": "Приложение с таким именем уже установлено, но с другой подписью",
 "：ApkStart 用官方绕过参数重试": ": ApkStart повторяет попытку с официальным параметром обхода",
 "应用依赖特定厂商环境，模拟器无法提供": "Приложение зависит от среды конкретного производителя, которую эмулятор не может обеспечить",
 "卸载冲突应用": "Удалите конфликтующее приложение",
 "：安装时报": ": при установке появляется сообщение",
 "一个通用 Android 14 镜像": "универсальный образ Android 14",
 "安装时若报": "если при установке появляется",
 "你需要做的：": "Что вам нужно сделать:",
 "：设置 → 常用与安装 → 运行时，看「通用兼容镜像（自动管理）」状态；若显示未下载，点「下载兼容镜像」（约 1.5 GB），完成后": ": Настройки → Общее и установка → Среда выполнения, проверьте состояние «Универсальный совместимый образ (автоматическое управление)»; если указано, что он не загружен, нажмите «Загрузить совместимый образ» (около 1.5 GB), после завершения",
 "：少数应用自带更深的反模拟检测（强制校验真实传感器、基带等），无法在模拟器里运行；这类应用会给出中文说明，属于限制，不是故障。": ": некоторые приложения используют более глубокую проверку на эмуляцию (принудительно проверяют реальные датчики, модем и т. д.) и не могут работать в эмуляторе; такие приложения выдают пояснение на китайском языке — это ограничение, а не неисправность.",
