 "的版本。": "версии.",
 "一定是缺 VC++ 运行库、也不等于一定是杀毒软件删了文件。同一个退出码背后有三种可能，别只按第一种反复重装：": "это не обязательно означает отсутствие библиотеки VC++ и не обязательно означает, что файлы удалил антивирус. За одним и тем же кодом выхода стоят три причины — не пытайтесь устранить его только первым способом и снова и снова переустанавливать:",
 "等子进程时，子进程按相对路径找 DLL，可能被容器的路径重定向 / 环境隔离打断，找不到依赖就退出": "при ожидании дочернего процесса тот ищет DLL по относительному пути; этому может помешать перенаправление путей / изоляция окружения контейнера, и если зависимость не найдена, процесс завершается",
