 "AVD / 已装应用 / 快照": "AVD / установленные приложения / снапшоты",
 "运行日志 / 诊断报告": "Журнал работы / диагностический отчёт",
 "诊断报告": "Диагностический отчёт",
 "：如\"商店版 0.6.3\"或\"完整便携版 0.6.3\"。": ": например, \"версия из магазина 0.6.3\" или \"полная портативная версия 0.6.3\".",
 "AMD 核显 · 改用 swangle 渲染（示例）": "Встроенная графика AMD · переключение на рендеринг swangle (пример)",
 "Intel 核显 · 软件渲染兜底（示例）": "Встроенная графика Intel · программный рендеринг в качестве запасного варианта (пример)",
 "机器没开「虚拟机监控程序平台」、也不允许装内核驱动时，emulator 走硬件加速会直接失败。这个补丁让 ApkStart 一开始就用软件模拟（-accel off），省掉两轮白等；同时把渲染后端换成 software，避免 GL 初始化失败。": "Если на компьютере не включена «Платформа гипервизора» и установка драйверов ядра запрещена, emulator с аппаратным ускорением сразу завершится ошибкой. Этот патч заставляет ApkStart сразу использовать программное моделирование (-accel off), избавляя от двух бесполезных ожиданий; одновременно бэкенд рендеринга заменяется на software, чтобы избежать ошибки инициализации GL.",
