 "遇到问题先做这一步：体检与自动检测": "При проблеме начните с этого: диагностика и автоматическая проверка",
 "桌面图标（真实应用图标 .lnk）\n      │ 双击\n      ▼\nApkStart.exe --launch <包名>\n      │ 安卓运行时没开？→ 自动拉起（Android 14 模拟器，随包内置或首次下载）\n      ▼\n按系统解析出的启动入口打开应用（不是 APK 里写死的主 Activity）\n      ▼\n模拟器窗口 = 应用窗口（改标题、换图标、竖屏比例、全屏居中）": "Ярлык на рабочем столе (реальный значок приложения .lnk)\n      │ двойной щелчок\n      ▼\nApkStart.exe --launch <имя пакета>\n      │ Среда Android не запущена? → автозапуск (эмулятор Android 14, встроен в пакет или загружается при первом запуске)\n      ▼\nПриложение открывается через точку входа, определённую системой (не через жёстко заданную в APK главную Activity)\n      ▼\nОкно эмулятора = окно приложения (изменение заголовка, значка, пропорций для портретного режима, центрирование на весь экран)",
 "每个应用一个桌面图标": "Один значок на рабочем столе для каждого приложения",
 "能被 Windows 搜到": "Находится через поиск Windows",
