 "形态": "Формат",
 "ApkStart_<四段版本>_x64.msix": "ApkStart_<четырёхсегментная версия>_x64.msix",
 "不想装、也不想等下载：解压即用，运行时全在包里": "Не хотите устанавливать и ждать загрузки: распаковали — и работает, среда выполнения целиком в пакете",
 "轻量便携版": "Лёгкая портативная версия",
 "。旧版（0.5.x 及更早）要么没有内置运行时、每次启动去找/下 1.5 GB 运行时，要么默认用嵌入窗口——这正是「很慢、打不开、出来一个带旋转按钮的窗口」的典型来源。如果你是从旧版升级，请确认桌面图标指向的是新版程序目录。": ". В старых версиях (0.5.x и ранее) либо не было встроенной среды выполнения, и при каждом запуске она искалась/загружалась (1.5 GB), либо по умолчанию использовалось встроенное окно — это и есть типичная причина «медленно, не открывается, появляется окно с кнопкой поворота». Если вы обновились со старой версии, убедитесь, что значок на рабочем столе указывает на каталог новой программы.",
 "：xz 镜像展开到": ": образ xz распаковывается в",
