 "命令行：": "Командная строка:",
 "）。装完自动生成桌面 + 开始菜单快捷方式。": "После установки автоматически создаются ярлыки на рабочем столе и в меню «Пуск».",
 "方法": "Способ",
 "（全局）或标题栏旋转按钮；方向会被这个应用记住": "(глобально) или кнопка поворота в строке заголовка; ориентация запоминается для этого приложения",
 "只有\"面板方向和应用方向不一致\"的那一次才会重启运行时（约 40 秒，标题栏会给提示），同方向的应用之后都秒进。": "Перезапуск среды выполнения происходит только в тот раз, когда «ориентация панели и приложения не совпадают» (около 40 секунд, в строке заголовка появится подсказка); в дальнейшем приложения с такой же ориентацией запускаются за секунды.",
 "旋转当前应用横竖屏": "Повернуть текущее приложение (альбомная/портретная ориентация)",
 "秒级双向同步。 入口：设置 → 集成与文件 → 文件互通（可\"立即同步\"或\"打开目录\"）。": "Двусторонняя синхронизация за секунды. Вход: Настройки → Интеграция и файлы → Обмен файлами (можно «Синхронизировать сейчас» или «Открыть папку»).",
 "运行时与环境、一键完成、开机自启、磁盘占用与清理": "Среда выполнения и окружение, всё в один клик, автозапуск, использование диска и очистка",
 "更新与下载源、加速镜像、下载线程数": "Обновления и источники загрузки, ускоряющие зеркала, число потоков загрузки",
