 "新版便携版支持": "Поддерживается в новой портативной версии",
 "大部分\"诡异问题\"，根源都在下面三样东西之一。花一分钟看懂，后面排查就顺了。": "Большинство «странных проблем» имеют корень в одном из трёх перечисленных ниже факторов. Потратьте минуту на понимание — и последующий поиск неисправностей пойдёт гладко.",
 "一个通用镜像": "Один универсальный образ",
 "）是薄差分层，系统镜像全机共享一份。": ") — это тонкий слой разностей, системный образ на компьютере хранится в одном экземпляре.",
 "谁需要管理员": "Кому нужны права администратора",
 "要": "Требуется",
