 "。只开前者，": ". Включите только первый,",
 "（arm64-v8a / armeabi-v7a），而系统镜像是": "(arm64-v8a / armeabi-v7a), а системный образ —",
 "老镜像（API 30）对新版翻译层有兼容问题（如字节系应用触发": "Старые образы (API 30) имеют проблему совместимости с новой версией слоя трансляции (например, приложения ByteDance вызывают",
 "查什么：CPU 虚拟化（VT-x/SVM）是否开、Hyper-V/虚拟机监控程序平台是否可用、显卡/显存/驱动、内存、系统版本、": "Что проверяется: включена ли виртуализация CPU (VT-x/SVM), доступны ли Hyper-V/платформа гипервизора, видеокарта/видеопамять/драйвер, оперативная память, версия системы,",
 "结果分级：": "Уровни результата:",
 "需要你亲自做的只有两类：": "Только два типа действий нужно выполнить лично:",
 "：见 6.1。": ": см. 6.1.",
 "（重启运行时、清锁、清孤儿进程、作废快照、清理磁盘、重置安卓网络……），修完自动复检：": "(перезапуск среды выполнения, сброс блокировок, удаление осиротевших процессов, аннулирование снимков, очистка диска, сброс сети Android...), после исправления автоматическая повторная проверка:",
 "磁盘余量、数据分区配置与实际不符、共享目录不可写": "Недостаточно места на диске, конфигурация раздела данных не соответствует реальной, общая папка недоступна для записи",
 "两条原则：探测失败不会被当成问题（拿不到状态就报\"不知道\"，绝不瞎报）；同一个老问题不重复打扰。": "Два принципа: неудачная проверка не считается проблемой (если не удалось получить состояние, сообщается «не знаю», никогда не выдумываем); одна и та же старая проблема не беспокоит повторно.",
