 "ApkStart.exe <路径\\to.apk>": "ApkStart.exe <путь\\to.apk>",
 "双击桌面图标即可。所有应用共用同一个运行时，所以": "Достаточно дважды щёлкнуть по значку на рабочем столе. Все приложения используют одну и ту же среду выполнения, поэтому",
 "全屏 / 窗口切换": "Переключение полный экран / окно",
 "设置 → 显示与窗口 → 自动全屏（配合\"强制方向\"效果最好）": "Настройки → Экран и окно → Автоматический полноэкранный режим (лучше всего работает с «Принудительной ориентацией»)",
