 "壳窗口内旋转（原生窗口模式下请用": "Поворот в окне-оболочке (в режиме нативного окна используйте",
 "从 0.6.0 起分八类，顶部有搜索框（输入\"横屏\"\"内存\"\"代理\"等关键词，跨分类命中）：": "Начиная с 0.6.0, настройки разделены на восемь категорий, сверху есть поле поиска (введите ключевые слова «горизонтальный экран», «память», «прокси» — результаты находятся во всех категориях):",
 "显示模式、自动全屏、屏幕方向、平板排版、窗口承载方式": "Режим отображения, автоматический полноэкранный режим, ориентация экрана, раскладка для планшета, способ размещения окна",
 "本机体检、驱动/兼容补丁、自动检测": "Диагностика системы, драйверы/патчи совместимости, автоматическое обнаружение",
 "实验室 · 多开（实验性）": "Лаборатория · несколько экземпляров (экспериментально)",
 "增量更新": "Инкрементальные обновления",
 "ApkStart 不是在模拟一个\"空安卓\"，而是加载一个": "ApkStart не эмулирует «пустой Android», а загружает",
 "（Google Play x86_64），x86 和 ARM 应用都靠它跑——不再像老版本那样分\"AOSP 镜像 / 兼容镜像\"两套。": "(Google Play x86_64), и x86-, и ARM-приложения работают через него — больше нет разделения на «образ AOSP / совместимый образ», как в старых версиях.",
 "模拟器要跑得快，需要 CPU 虚拟化加速。Windows 上只有两条路：": "Чтобы эмулятор работал быстро, нужна аппаратная виртуализация CPU. В Windows есть только два пути:",
 "装完要重启吗": "Нужно ли перезагружаться после установки",
 "Google 自家内核驱动": "Собственный драйвер ядра от Google",
 "（纯软件模拟 TCG），只是开机慢到几分钟、画面易掉帧——这是\"慢\"，不是\"启动失败\"。ApkStart 会自动回退，并且按\"渲染后端 → 加速方式 → 内存/冷启动\"最多 4 组参数自动重试。": "(чисто программная эмуляция TCG), только загрузка занимает несколько минут, а изображение часто подтормаживает — это «медленно», а не «сбой запуска». ApkStart автоматически откатится и выполнит до 4 наборов параметров автоматических повторов в порядке «бэкенд рендеринга → ускорение → память/холодный запуск».",
 "依然说不可用。": "по-прежнему сообщает, что недоступно.",
 "的——需要一个\"翻译层\"把 ARM 指令转给 x86 CPU。0.6.3 的通用镜像内置了新版": "— необходим «слой трансляции», который преобразует инструкции ARM для x86 CPU. Универсальный образ в версии 0.6.3 включает новую версию",
 "SIGABRT），Android 14 镜像已修复。": "SIGABRT), в образе Android 14 это исправлено.",
 "、AEHD 驱动。": ", драйвер AEHD.",
 "（正常）/": "(норма)/",
 "BIOS 虚拟化": "Виртуализация BIOS",
 "位置：设置 → 诊断与修复 →「自动检测 · 智能诊断」": "Раздел: Настройки → Диагностика и восстановление → «Автоматическое обнаружение · Интеллектуальная диагностика»",
 "覆盖的问题": "Охватываемые проблемы",
 "屏幕方向与物理面板冲突、独立窗口下自动全屏不生效": "Конфликт ориентации экрана с физической панелью, автоматический полноэкранный режим не работает в отдельном окне",
 "（或系统集成页同名按钮）": "(или одноимённая кнопка на странице «Интеграция с системой»)",
 "：主界面标题栏的「?」按钮、设置 → 关于里的「打开使用手册」都能直接打开，可搜索、滚动、打印/存 PDF。打开时会自动定位到与当前故障相关的章节。": ": Кнопка «?» в строке заголовка главного окна и «Открыть руководство пользователя» в разделе Настройки → О программе открывают его напрямую; доступны поиск, прокрутка, печать/сохранение в PDF. При открытии раздел автоматически переходит к главе, связанной с текущей проблемой.",
 "自动修复失败后，会自动弹出相应教程": "Если автоматическое восстановление не удалось, автоматически открывается соответствующая инструкция",
